import {useState} from 'react';
import { BrowserRouter, Routes, Route, Link, useNavigate } from 'react-router-dom';

function NavigationButton({ path, title, color }) {
    const navigate = useNavigate();

    const handleClick = () => {
        navigate(path);
    };

    return (
        <button 
            onClick={handleClick}
            style={{ backgroundColor: color, color: 'white', padding: '10px 20px', margin: '5px' }}
        >
            {title}
        </button>
    );
}


export function Home() {
    return (
        <>
            <NavigationButton
            title="Play"
            color="#1a3caa"
            path="/hub"
            />

            <NavigationButton
            title="Leaderboard"
            color="#1a9c2a"
            path="/leaderboard"
            />

            <NavigationButton
            title="About"
            color="#aa3c3a"
            path="/about"
            />
        </>
    )

}

export function Hub() {
    return <h1>Hub</h1>
}

export function About() {
    return <h1>About</h1>
}

export function Leaderboard() {
    return <h1>Leaderboard</h1>
}
